(function () {
  console.warn("⚠️ Techlystb fallback JS activated");

  const box = document.createElement("div");
  box.innerHTML = `
    <div style="margin-bottom:5px;">
      🚫 <b>The main feature is not loaded.</b><br/>
      Fallback Launched.
    </div>
    <button onclick="location.reload()" style="margin:5px 5px 0 0;">🔁 Reload</button>
    <a href="https://wa.me/8801715569959" target="_blank" style="text-decoration:none;">
      <button style="margin-top:5px;">💬 WhatsApp</button>
    </a>
    <div id="retry-status" style="margin-top:8px;font-size:12px;opacity:0.6;"></div>
  `;
  box.style = `
    position:fixed;
    bottom:20px;
    left:20px;
    background:#1e1e1e;
    color:#fff;
    padding:16px;
    border:1px solid #444;
    border-radius:10px;
    font-family:sans-serif;
    font-size:14px;
    box-shadow:0 0 12px rgba(0,0,0,0.4);
    z-index:9999;
    max-width:90%;
    width:250px;
  `;
  document.body.appendChild(box);

  // Auto Retry Logic
  const retryStatus = box.querySelector("#retry-status");
  let retryCount = 0;
  const maxRetry = 5;

  function tryReload() {
    retryCount++;
    retryStatus.innerText = `🔄 Try again (${retryCount}/${maxRetry})...`;

    const testScript = document.createElement('script');
    testScript.src = 'https://cdn.jsdelivr.net/gh/Techlystb/Tech@latest/Techystb-v1.min.js';
    testScript.onload = function () {
      location.reload(); // success হলে পেজ রিলোড
    };
    testScript.onerror = function () {
      if (retryCount < maxRetry) {
        setTimeout(tryReload, 10000); // প্রতি ১০ সেকেন্ডে রি-ট্রাই
      } else {
        retryStatus.innerText = "❌ The best effort has been completed.";
      }
    };
    document.head.appendChild(testScript);
  }

  setTimeout(tryReload, 5000); // ৫ সেকেন্ড পর প্রথম চেষ্টা
})();
